// SLUGBERT — a green slug that lunges with its overhanging lip and leaves slime everywhere it crawls.
// Drawn fighter: a plain ES module, no imports, everything from `api`.
//
//   STRIKE   (attack button)   the dome lunges and the lip slaps down. Aimed forward, up or down; charged for the smash.
//   GIMMICK  (special button)  SLIME TRAIL: the foot leaves slime; Slugbert glides at double speed on it, everyone else slips.
//                              Neutral surges forward laying a strip, sideways hocks a gob that puddles, down spreads a pool.
//   RECOVERY (up + special)    the foot slaps down and the body snaps up like a rubber tube.
//   GRAB     (grab button)     swallows them into the mouth notch, then spits them the way you hold.
//
// Fighter space: +x is the facing direction, +y is DOWN, the origin is at the feet. Frames are 1-based.
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spawnProjectile, spriteAnims, spriteLoops } = api;

  const stats = {
    weight: 115, walk: 2.2, run: 3.6, dashInit: 4.2, airSpeed: 2.8, airAccel: 0.14,
    fallSpeed: 7.4, fastFall: 11, gravity: 0.52, shortHop: 7, fullHop: 10.5, doubleJump: 9,
    jumps: 2, wallJump: true, traction: 0.7, height: 89, width: 60, crouchHeight: 52, landLag: 6, ledgeReach: 30,
  };

  // A blob: it squashes and stretches more than it leans.
  const P = (extra) => ({ a: {}, ...extra });
  const rest = P({});
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.9, sy: 1.08, ...extra })),
    key(hit, P({ rot: lean, sx: 1.14, sy: 0.9, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.6, sx: 1.05, sy: 0.97, ...extra })),
    key(total, rest),
  ];
  const SLAP = { fx: "heavy" };
  const SLIME = { fx: "energy" };

  // THE STRIKE: the overhanging lip at the front of the dome (about 26-40 units up) slaps down, 12 damage.
  // Each aiming: [capsule start, capsule end, angle, lean], placed on the drawn lip of its cell.
  const STRIKE = { total: 34, hit: 11, active: 4, damage: 12, r: 14 };
  const LINE = {
    f: [[16, -40], [38, -26], 40, 8],
    u: [[2, -44], [2, -66], 88, -4],
    b: [[-16, -40], [-38, -26], 40, -8],
    d: [[8, -14], [38, -8], 30, 4],
  };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const [start, end, angle, lean] = s.line ?? LINE[dir];
    const extra = dir === "d" ? { sy: 0.9, dy: 2 } : dir === "u" ? { sy: 1.1 } : {};
    const cell = dir === "u" ? "atk-up" : dir === "d" ? "atk-down" : "atk-fwd";
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, angle, s.base ?? 40, s.growth ?? 82, { ...SLAP, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, extra), { cell, cellFlip: dir === "b", ...(s.mv ?? {}) });
  };
  // GRAB: swallowed into the mouth notch, spat out the way you hold
  const GRAB = { total: 38, hit: 8, damage: 9 };
  const spit = (id, angle, base, growth, pose) => throwMove(id, 34, 16, GRAB.damage, angle, base, growth, [key(0, P({ sx: 1.12, sy: 1.06 })), key(16, P(pose)), key(34, rest)]);

  // SLIME: a ring of N puddles on the special state; each slot is x, y (floor height), w (half-width), t (frames left).
  const N = 16;
  const stamp = (state, f, x, y, w, life) => {
    const s = f.special;
    const i = s.next;
    s["x" + i] = x; s["y" + i] = y; s["w" + i] = w; s["t" + i] = life;
    s.next = (i + 1) % N;
    spawnProjectile(state, f, "slime", x, y - 2, 0, 0, life,
      { frames: [100000, 100000], x: 0, y: 0, r: Math.min(w, 30), damage: 0, angle: 0, base: 0, growth: 0 }, { g: 0 });
  };
  const onSlime = (s, x, y) => {
    for (let i = 0; i < N; i++) {
      if (s["t" + i] > 0 && Math.abs(y - s["y" + i]) < 6 && Math.abs(x - s["x" + i]) <= s["w" + i]) return true;
    }
    return false;
  };

  const moves = {
    // strike, forward
    jab1: aim("jab1", "f", { total: 26, hit: 8, damage: 8, mv: { iasa: 20 } }),
    ftilt: aim("ftilt", "f"),
    dashAttack: aim("dashAttack", "f", { total: 40, hit: 10, damage: 11, mv: { motion: [[1, 6, 0], [12, 3, 0], [22, 1, 0]] } }),
    nair: aim("nair", "f", { total: 32, hit: 9, damage: 10, mv: { aerial: true, landingLag: 10 } }),
    fair: aim("fair", "f", { mv: { aerial: true, landingLag: 12 } }),
    bair: aim("bair", "b", { damage: 13, mv: { aerial: true, landingLag: 12 } }),
    // strike, up: the dome bonks upward
    utilt: aim("utilt", "u", { damage: 11 }),
    uair: aim("uair", "u", { damage: 11, mv: { aerial: true, landingLag: 10 } }),
    // strike, down: the lip smears the floor; in the air a belly-flop that spikes
    dtilt: aim("dtilt", "d", { total: 30, hit: 9, damage: 10, r: 12 }),
    dair: aim("dair", "d", { total: 42, hit: 14, damage: 13, r: 13, line: [[-22, -6], [30, -6], 270, 4], base: 30, growth: 70, hb: { spike: true }, mv: { aerial: true, landingLag: 16 } }),
    // the charged strike: coils back, splats forward, sweetspot on the lip
    fsmash: mv("fsmash", 54, [
      cap([18, 21], 18, -40, 40, -26, 16, 19, 40, 46, 100, { ...SLAP, priority: 0 }),
      cap([18, 23], 0, -36, 22, -30, 18, 15, 42, 40, 84, { ...SLAP, priority: 1 }),
    ], [key(0, P({ sx: 0.96, sy: 1.04 })), key(12, P({ rot: -10, sx: 0.84, sy: 1.12, dx: -6 })), key(18, P({ rot: 12, sx: 1.24, sy: 0.84, dx: 8 })), key(28, P({ rot: 8, sx: 1.1, sy: 0.94, dx: 4 })), key(54, rest)], { smash: true, cell: "atk-fwd" }),
    usmash: aim("usmash", "u", { total: 50, hit: 15, active: 6, damage: 17, r: 16, base: 42, growth: 98, mv: { smash: true } }),
    dsmash: mv("dsmash", 54, [
      cap([17, 21], 6, -10, 42, -6, 13, 16, 30, 44, 90, { ...SLAP, group: 0 }),
      cap([17, 21], -6, -10, -46, -6, 13, 16, 30, 44, 90, { ...SLAP, group: 0 }),
    ], [key(0, P({ sy: 1.08, sx: 0.92 })), key(17, P({ sx: 1.22, sy: 0.8, dy: 2 })), key(26, P({ sx: 1.12, sy: 0.88 })), key(54, rest)], { smash: true, cell: "atk-down" }),
    // grab: the mouth notch swallows them
    grab: mv("grab", GRAB.total, [hb([GRAB.hit, GRAB.hit + 2], 30, -36, 16, 0, 0, 0, 0, { grab: true })], strikePoses(GRAB.total, GRAB.hit, 8), { isGrab: true }),
    dashGrab: mv("dashGrab", 44, [hb([10, 12], 34, -36, 18, 0, 0, 0, 0, { grab: true })], strikePoses(44, 10, 12), { isGrab: true, motion: [[1, 4, 0], [10, 0, 0]] }),
    pummel: mv("pummel", 16, [], [key(0, P({ sx: 1.08, sy: 1.04 })), key(6, P({ sx: 1.16, sy: 1.1 })), key(16, P({ sx: 1.08, sy: 1.04 }))]),
    fthrow: spit("fthrow", 42, 60, 74, { rot: 14, sx: 1.2, sy: 0.9 }),
    bthrow: spit("bthrow", 40, 64, 80, { rot: -16, sx: 1.12 }),
    uthrow: spit("uthrow", 90, 70, 90, { sy: 1.2, sx: 0.88, dy: -6 }),
    dthrow: spit("dthrow", 70, 45, 44, { sy: 0.82, sx: 1.18, dy: 4 }),
    // GIMMICK, SLIME TRAIL: surge forward on a fresh strip of slime, body first (costs 25 slime; dry it is a slow shove)
    nspecial: mv("nspecial", 46, [cap([10, 22], 0, -32, 32, -30, 16, 10, 38, 50, 78, SLIME)], [key(0, P({ sx: 0.88, sy: 1.1 })), key(8, P({ rot: 10, sx: 1.2, sy: 0.86 })), key(24, P({ rot: 6, sx: 1.12, sy: 0.9 })), key(46, rest)], { hook: "surge", cell: "atk-fwd" }),
    // held sideways: hocks a lobbed gob from the mouth notch that puddles where it lands (costs 15)
    sspecial: mv("sspecial", 40, [], [key(0, P({ rot: -6, sx: 0.9, sy: 1.1 })), key(14, P({ rot: 10, sx: 1.12, sy: 0.9 })), key(22, P({ rot: 6 })), key(40, rest)], { hook: "gob", cell: "atk-fwd" }),
    // held down: slams flat and spreads a big pool underneath, the splash pops them up (costs 35)
    dspecial: mv("dspecial", 44, [cap([16, 19], -42, -6, 42, -6, 12, 6, 80, 40, 40, SLIME)], [key(0, P({ sy: 1.06 })), key(12, P({ sy: 0.8, sx: 1.16 })), key(16, P({ sy: 0.72, sx: 1.26 })), key(30, P({ sy: 0.86, sx: 1.1 })), key(44, rest)], { hook: "pool", cell: "atk-down", fx: "quake" }),
    // RECOVERY, RUBBER TUBE: the foot slaps, the body stretches, then snaps up, steerable
    uspecial: mv("uspecial", 60, [cap([9, 14], 0, -40, 0, -72, 16, 9, 85, 45, 60, SLAP)], [key(0, rest), key(6, P({ sy: 0.7, sx: 1.25 })), key(9, P({ sy: 1.3, sx: 0.8 })), key(30, P({ sy: 1.12, sx: 0.9 })), key(60, rest)], { hook: "stretch", helpless: true, ledgeOk: true, cell: "atk-up" }),
    ledgeAttack: aim("ledgeAttack", "f", { total: 40, hit: 12, damage: 9 }),
    getupAttack: mv("getupAttack", 44, [cap([12, 15], 6, -10, 40, -6, 13, 7, 40, 40, 60, { ...SLAP, group: 0 }), cap([20, 23], -6, -10, -44, -6, 13, 7, 40, 40, 60, { ...SLAP, group: 1 })], [key(0, rest), key(12, P({ rot: 8, sx: 1.18, sy: 0.84 })), key(20, P({ rot: -8, sx: 1.18, sy: 0.84 })), key(44, rest)], { cell: "atk-down" }),
    taunt: mv("taunt", 50, [], [key(0, rest), key(12, P({ sy: 1.14, sx: 0.9 })), key(24, P({ sy: 0.86, sx: 1.12 })), key(36, P({ sy: 1.08, sx: 0.94 })), key(50, rest)]),
  };

  return {
    id: "slugbert", // replaced by the forge with the player's fighter id
    name: "SLUGBERT",
    tagline: "Slow, wet, and already where you were about to stand.",
    stats,
    moves,
    rig: { bones: [], anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: "#3a9a4f" }, accent: "marker", outline: "#1e1e1c" },
    looks: {
      slime: { shape: "puddle", color: "#5fc94a", ink: "#1f7a2e", texture: "dots", aim: false },
      gob: { shape: "blob", color: "#5fc94a", ink: "#1f7a2e", texture: "dots", spin: 9, trail: "smoke" },
    },
    // every key must exist from the start: the state hash walks these
    special: () => {
      const s = { slime: 100, next: 0, surge: 0, gobT: 0, gobX: 0, gobY: 0 };
      for (let i = 0; i < N; i++) { s["x" + i] = 0; s["y" + i] = 0; s["w" + i] = 0; s["t" + i] = 0; }
      return s;
    },
    hooks: {
      surge: ({ state, f }) => {
        const s = f.special;
        if (f.frame === 6) { s.surge = s.slime >= 25 ? 1 : 0; s.slime -= s.surge * 25; }
        if (f.frame >= 8 && f.frame <= 24) {
          f.vx = f.moveFacing * (s.surge ? 8.5 : 4.5);
          if (s.surge && f.grounded && f.frame % 4 === 0) stamp(state, f, f.x, f.y, 20, 240);
        }
      },
      gob: ({ state, f }) => {
        if (f.frame !== 14) return;
        const s = f.special;
        const x = f.x + f.moveFacing * 34;
        const vx = f.moveFacing * 5.5;
        // launched 40 up at vy -4.5 under g 0.3, the gob is back at floor height 37 frames later
        const t = 37;
        spawnProjectile(state, f, "gob", x, f.y - 40, vx, -4.5, f.grounded ? t : 90,
          { frames: [0, 999], x: 0, y: 0, r: 10, damage: 6, angle: 50, base: 30, growth: 45 }, { g: 0.3 });
        if (f.grounded && s.slime >= 15) { s.slime -= 15; s.gobT = t; s.gobX = x + vx * t; s.gobY = f.y; }
      },
      pool: ({ state, f }) => {
        const s = f.special;
        if (f.frame === 16 && f.grounded && s.slime >= 35) { s.slime -= 35; stamp(state, f, f.x, f.y, 64, 420); }
      },
      stretch: ({ f, input }) => {
        if (f.frame <= 8) {
          if (!f.grounded) f.vy = Math.min(f.vy, 0.5);
          f.vx *= 0.9;
          return;
        }
        if (f.frame === 9) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame <= 40) {
          f.vy = -9.5 + (f.frame - 9) * 0.22;
          f.vx = (input.x / 100) * 6.2;
        }
      },
    },
    onFrame: ({ state, f }) => {
      const s = f.special;
      for (let i = 0; i < N; i++) if (s["t" + i] > 0) s["t" + i]--;
      if (s.gobT > 0) {
        s.gobT--;
        if (s.gobT === 0) stamp(state, f, s.gobX, s.gobY, 30, 300);
      }
      s.slime = Math.min(100, s.slime + 0.2);
      if (f.grounded) {
        const slick = onSlime(s, f.x, f.y);
        const speed = Math.abs(f.vx);
        // walking or running on its own slime: double speed
        if (slick && speed > 0.5 && speed <= stats.run + 0.5) f.x += f.vx;
        if (!slick && speed > 1 && s.slime >= 3) { s.slime -= 3; stamp(state, f, f.x, f.y, 14, 180); }
      }
      for (const g of state.fighters) {
        if (g === f || !g.grounded || Math.abs(g.vx) <= 1 || !onSlime(s, g.x, g.y)) continue;
        // everyone else slips: their slide keeps going
        g.vx = Math.max(-6, Math.min(6, g.vx + (g.vx > 0 ? 0.25 : -0.25)));
      }
    },
    meters: [{ label: "SLIME", color: "#3a9a4f", get: (f) => f.special.slime / 100 }],
    visual: (f) => ({ glow: f.special.slime / 400 }),
  };
}
